import os
import json
import time
import socket
from typing import Any, Dict, Optional

import boto3
from botocore.exceptions import ClientError


def write_structured_log_event(
    log_group_name: str,
    log_stream_name: str,
    event: Dict[str, Any],
    region_name: Optional[str] = None,
) -> Dict[str, Any]:
    client = boto3.client("logs", region_name=region_name or os.getenv("AWS_REGION"))

    try:
        client.create_log_group(logGroupName=log_group_name)
    except ClientError as e:
        code = e.response.get("Error", {}).get("Code", "")
        if code != "ResourceAlreadyExistsException":
            raise

    try:
        client.create_log_stream(
            logGroupName=log_group_name,
            logStreamName=log_stream_name,
        )
    except ClientError as e:
        code = e.response.get("Error", {}).get("Code", "")
        if code != "ResourceAlreadyExistsException":
            raise

    payload = {
        "timestamp_iso": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
        "host": socket.gethostname(),
        **event,
    }

    message = json.dumps(payload, separators=(",", ":"), default=str)
    timestamp_ms = int(time.time() * 1000)

    response = client.put_log_events(
        logGroupName=log_group_name,
        logStreamName=log_stream_name,
        logEvents=[
            {
                "timestamp": timestamp_ms,
                "message": message,
            }
        ],
    )

    return {
        "provider": "aws",
        "service": "cloudwatch-logs",
        "log_group_name": log_group_name,
        "log_stream_name": log_stream_name,
        "next_sequence_token": response.get("nextSequenceToken"),
        "rejected_log_events_info": response.get("rejectedLogEventsInfo"),
    }
